const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const geometry = ee.Geometry.Polygon(
    [[[-5.5, 13.8], [-3.5, 13.8], [-3.5, 15.5], [-5.5, 15.5], [-5.5, 13.8]]],
    null, false
  );
  const startDate1 = '2022-05-01';
  const endDate1 = '2022-05-31';
  const startDate2 = '2022-11-01';
  const endDate2 = '2022-11-30';
  const scale = 3000; // Use a coarse scale for a large area to avoid timeouts

  // Function to mask clouds using the Sentinel-2 SCL band.
  function maskS2clouds(image) {
    const scl = image.select('SCL');
    // Keep vegetation, non-vegetated, water, and unclassified.
    const desiredPixels = scl.eq(4).or(scl.eq(5)).or(scl.eq(6)).or(scl.eq(7));
    return image.updateMask(desiredPixels);
  }

  // Function to calculate NDVI.
  function addNDVI(image) {
    const ndvi = image.normalizedDifference(['B8', 'B4']).rename('NDVI');
    return image.addBands(ndvi);
  }

  // Generic function to process a collection for a given period
  const getPeriodMean = (startDate, endDate, periodName) => {
    // 2. Data Acquisition & Check
    let collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterBounds(geometry)
      .filterDate(startDate, endDate);

    const collectionSize = collection.size().getInfo();
    if (collectionSize === 0) {
      return { status: 'C1', message: `No images found for ${periodName}.` };
    }

    // 3. Processing
    const composite = collection
      .map(maskS2clouds)
      .map(addNDVI)
      .select('NDVI')
      .median(); // Median composite to reduce remaining cloud/haze effects

    // 4. Calculation
    const stats = composite.reduceRegion({
      reducer: ee.Reducer.mean().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
      }),
      geometry: geometry,
      scale: scale,
      maxPixels: 1e9
    });

    const meanNdvi = stats.get('NDVI_mean').getInfo();
    const pixelCount = stats.get('NDVI_count').getInfo();

    // Check for C2 case
    if (pixelCount === 0) {
      return { status: 'C2', message: `No valid pixels after masking for ${periodName}.`, ndvi: null, count: 0, size: collectionSize };
    }

    // Check for C3 case
    if (meanNdvi === null || meanNdvi === undefined) {
      return { status: 'C3', message: `Calculation failed for ${periodName}.`, ndvi: null, count: pixelCount, size: collectionSize };
    }

    return { status: 'Success', ndvi: meanNdvi, count: pixelCount, size: collectionSize };
  };

  const mayResult = getPeriodMean(startDate1, endDate1, "May 2022");
  if (mayResult.status !== 'Success') {
    console.log(mayResult.message);
    console.log(mayResult.status);
    return;
  }

  const novResult = getPeriodMean(startDate2, endDate2, "Nov 2022");
  if (novResult.status !== 'Success') {
    console.log(novResult.message);
    console.log(novResult.status);
    return;
  }

  // 5. Validation & Final Answer
  console.log(`May 2022 Images: ${mayResult.size}`);
  console.log(`May 2022 Mean NDVI: ${mayResult.ndvi.toFixed(4)}`);
  console.log(`May 2022 Valid Pixels: ${mayResult.count}`);

  console.log(`Nov 2022 Images: ${novResult.size}`);
  console.log(`Nov 2022 Mean NDVI: ${novResult.ndvi.toFixed(4)}`);
  console.log(`Nov 2022 Valid Pixels: ${novResult.count}`);

  if (novResult.ndvi > mayResult.ndvi) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(e => {
  console.error(e);
  console.log("D");
});
